QspiOutputStatus:
        PSHM    CCR
        ORP     #$00E0
        BRSET   >SystemFlags945,Z,#$80,L38214            ; bit 7: QSPI transfer running (set by QspiSendFrame, cleared by QspiService)
        CLRW    >SPCR2,Z
        LDD     >SwitchBits0,Z
        STD     >TR0,Z
        JSR     QspiWaitIdle
        LDE     >RR0,Z
